reply.content:
{
  "semantic_models": [
    {
      "name": "order_semantic",
      "model": "ref('orders_enriched')",
      "defaults": {
        "agg_time_dimension": "ordered_at"
      },
      "entities": [
        {
          "name": "order",
          "type": "primary",
          "expr": "order_id"
        },
        {
          "name": "member",
          "type": "foreign",
          "expr": "member_id"
        },
        {
          "name": "store",
          "type": "foreign",
          "expr": "store_id"
        },
        {
          "name": "home_store",
          "type": "foreign",
          "expr": "home_store_id"
        }
      ],
      "dimensions": [
        {
          "name": "ordered_at",
          "type": "time",
          "type_params": {
            "time_granularity": "day"
          }
        },
        {
          "name": "channel",
          "type": "categorical"
        },
        {
          "name": "status",
          "type": "categorical"
        }
      ],
      "measures": [
        {
          "name": "m_order_count",
          "expr": "1",
          "agg": "sum"
        },
        {
          "name": "m_paid_order_count",
          "expr": "case when status = 'paid' then 1 else 0 end",
          "agg": "sum"
        },
        {
          "name": "m_valid_order_count",
          "expr": "case when status = 'paid' and paid_cents - refund_cents > 0 then 1 else 0 end",
          "agg": "sum"
        },
        {
          "name": "m_cancelled_order_count",
          "expr": "case when status = 'cancelled' then 1 else 0 end",
          "agg": "sum"
        },
        {
          "name": "m_refund_order_count",
          "expr": "case when status = 'paid' and refund_cents > 0 then 1 else 0 end",
          "agg": "sum"
        },
        {
          "name": "m_partial_refund_order_count",
          "expr": "case when status = 'paid' and refund_cents > 0 and refund_cents < paid_cents then 1 else 0 end",
          "agg": "sum"
        },
        {
          "name": "m_full_refund_order_count",
          "expr": "case when status = 'paid' and paid_cents > 0 and refund_cents = paid_cents then 1 else 0 end",
          "agg": "sum"
        },
        {
          "name": "m_payment_cents",
          "expr": "case when status = 'paid' then paid_cents else 0 end",
          "agg": "sum"
        },
        {
          "name": "m_refund_cents",
          "expr": "case when status = 'paid' then refund_cents else 0 end",
          "agg": "sum"
        },
        {
          "name": "m_net_sales_cents",
          "expr": "case when status = 'paid' then paid_cents - refund_cents else 0 end",
          "agg": "sum"
        },
        {
          "name": "m_gross_cents",
          "expr": "case when status = 'paid' then gross_cents else 0 end",
          "agg": "sum"
        },
        {
          "name": "m_discount_cents",
          "expr": "case when status = 'paid' then gross_cents - paid_cents else 0 end",
          "agg": "sum"
        },
        {
          "name": "m_buyer_count_distinct",
          "expr": "case when status = 'paid' and paid_cents - refund_cents > 0 then member_id end",
          "agg": "count_distinct"
        },
        {
          "name": "m_refund_buyer_count_distinct",
          "expr": "case when status = 'paid' and refund_cents > 0 then member_id end",
          "agg": "count_distinct"
        },
        {
          "name": "m_selling_store_count_distinct",
          "expr": "case when status = 'paid' and paid_cents - refund_cents > 0 then store_id end",
          "agg": "count_distinct"
        },
        {
          "name": "m_valid_order_items",
          "expr": "case when status = 'paid' and paid_cents - refund_cents > 0 then quantity else 0 end",
          "agg": "sum"
        }
      ]
    },
    {
      "name": "order_history_semantic",
      "model": "ref('valid_orders_sequenced')",
      "defaults": {
        "agg_time_dimension": "ordered_at"
      },
      "entities": [
        {
          "name": "history_order",
          "type": "primary",
          "expr": "order_id"
        },
        {
          "name": "member",
          "type": "foreign",
          "expr": "member_id"
        },
        {
          "name": "store",
          "type": "foreign",
          "expr": "store_id"
        },
        {
          "name": "home_store",
          "type": "foreign",
          "expr": "home_store_id"
        }
      ],
      "dimensions": [
        {
          "name": "ordered_at",
          "type": "time",
          "type_params": {
            "time_granularity": "day"
          }
        },
        {
          "name": "channel",
          "type": "categorical"
        },
        {
          "name": "status",
          "type": "categorical"
        }
      ],
      "measures": [
        {
          "name": "m_first_buyer_count_distinct",
          "expr": "case when order_rank = 1 then member_id end",
          "agg": "count_distinct"
        },
        {
          "name": "m_first_order_sales_cents",
          "expr": "case when order_rank = 1 then net_sales_cents else 0 end",
          "agg": "sum"
        },
        {
          "name": "m_first_order_count",
          "expr": "case when order_rank = 1 then 1 else 0 end",
          "agg": "sum"
        },
        {
          "name": "m_repeat_order_count",
          "expr": "case when order_rank >= 2 then 1 else 0 end",
          "agg": "sum"
        }
      ]
    },
    {
      "name": "monthly_account_orders_semantic",
      "model": "ref('monthly_account_orders')",
      "defaults": {
        "agg_time_dimension": "month_start"
      },
      "entities": [
        {
          "name": "monthly_account_order",
          "type": "primary",
          "expr": "member_month_key"
        },
        {
          "name": "member",
          "type": "foreign",
          "expr": "member_id"
        }
      ],
      "dimensions": [
        {
          "name": "month_start",
          "type": "time",
          "type_params": {
            "time_granularity": "month"
          }
        }
      ],
      "measures": [
        {
          "name": "m_monthly_buyer_count_distinct",
          "expr": "member_id",
          "agg": "count_distinct"
        },
        {
          "name": "m_monthly_repeat_buyer_count_distinct",
          "expr": "case when order_count >= 2 then member_id end",
          "agg": "count_distinct"
        }
      ]
    },
    {
      "name": "members_semantic",
      "model": "ref('members')",
      "defaults": {
        "agg_time_dimension": "registered_at"
      },
      "entities": [
        {
          "name": "member",
          "type": "primary",
          "expr": "member_id"
        },
        {
          "name": "home_store",
          "type": "foreign",
          "expr": "home_store_id"
        }
      ],
      "dimensions": [
        {
          "name": "registered_at",
          "type": "time",
          "type_params": {
            "time_granularity": "day"
          }
        },
        {
          "name": "tier",
          "type": "categorical"
        }
      ],
      "measures": [
        {
          "name": "m_new_member_count_distinct",
          "expr": "member_id",
          "agg": "count_distinct"
        }
      ]
    },
    {
      "name": "store_semantic",
      "model": "ref('store_dimension')",
      "entities": [
        {
          "name": "store",
          "type": "primary",
          "expr": "store_id"
        }
      ],
      "dimensions": [
        {
          "name": "region",
          "type": "categorical"
        },
        {
          "name": "store_name",
          "type": "categorical"
        }
      ]
    },
    {
      "name": "home_store_semantic",
      "model": "ref('home_store_dimension')",
      "entities": [
        {
          "name": "home_store",
          "type": "primary",
          "expr": "store_id"
        }
      ],
      "dimensions": [
        {
          "name": "region",
          "type": "categorical"
        },
        {
          "name": "store_name",
          "type": "categorical"
        }
      ]
    },
    {
      "name": "monthly_paid_semantic",
      "model": "ref('monthly_paid_month')",
      "defaults": {
        "agg_time_dimension": "month_start"
      },
      "entities": [
        {
          "name": "paid_month",
          "type": "primary",
          "expr": "month_key"
        }
      ],
      "dimensions": [
        {
          "name": "month_start",
          "type": "time",
          "type_params": {
            "time_granularity": "month"
          }
        }
      ],
      "measures": [
        {
          "name": "m_monthly_paid_buyer_count",
          "expr": "paid_buyer_count",
          "agg": "sum"
        },
        {
          "name": "m_monthly_paid_order_count",
          "expr": "paid_order_count",
          "agg": "sum"
        },
        {
          "name": "m_monthly_paid_sales_cents",
          "expr": "paid_sales_cents",
          "agg": "sum"
        },
        {
          "name": "m_monthly_paid_repeat_buyer_count",
          "expr": "paid_repeat_buyer_count",
          "agg": "sum"
        }
      ]
    }
  ],
  "metrics": [
    {
      "name": "order_count",
      "label": "创建订单数",
      "description": "按下单日期统计全部订单，每个订单号一次，包含取消单。单位：单。",
      "type": "simple",
      "type_params": {
        "measure": "m_order_count"
      }
    },
    {
      "name": "paid_order_count",
      "label": "支付订单数",
      "description": "状态为 paid 的订单数，包括后来全部退款的订单。单位：单。",
      "type": "simple",
      "type_params": {
        "measure": "m_paid_order_count"
      }
    },
    {
      "name": "valid_order_count",
      "label": "有效订单数",
      "description": "状态为 paid 且实付金额减退款金额大于零的订单数；取消和全退不计。单位：单。",
      "type": "simple",
      "type_params": {
        "measure": "m_valid_order_count"
      }
    },
    {
      "name": "cancelled_order_count",
      "label": "取消订单数",
      "description": "状态为 cancelled 的订单数。单位：单。",
      "type": "simple",
      "type_params": {
        "measure": "m_cancelled_order_count"
      }
    },
    {
      "name": "refund_order_count",
      "label": "退款订单数",
      "description": "paid 状态且退款金额大于零的订单数，包括部分退款与全部退款。单位：单。",
      "type": "simple",
      "type_params": {
        "measure": "m_refund_order_count"
      }
    },
    {
      "name": "partial_refund_order_count",
      "label": "部分退款订单数",
      "description": "paid 状态且退款大于零、小于实付金额的订单数。单位：单。",
      "type": "simple",
      "type_params": {
        "measure": "m_partial_refund_order_count"
      }
    },
    {
      "name": "full_refund_order_count",
      "label": "全额退款订单数",
      "description": "paid 状态且实付大于零、退款等于实付的订单数。单位：单。",
      "type": "simple",
      "type_params": {
        "measure": "m_full_refund_order_count"
      }
    },
    {
      "name": "payment_cents",
      "label": "实付金额",
      "description": "paid 订单实付金额合计，尚未扣退款；单位：分。",
      "type": "simple",
      "type_params": {
        "measure": "m_payment_cents"
      }
    },
    {
      "name": "refund_cents",
      "label": "退款金额",
      "description": "paid 订单退款金额合计，按原订单下单日期归属，不是现金退款发生日；单位：分。",
      "type": "simple",
      "type_params": {
        "measure": "m_refund_cents"
      }
    },
    {
      "name": "net_sales_cents",
      "label": "净销售额",
      "description": "paid 订单实付减退款后合计；取消单不计；按原订单下单日期归属；单位：分。",
      "type": "simple",
      "type_params": {
        "measure": "m_net_sales_cents"
      }
    },
    {
      "name": "gross_cents",
      "label": "支付订单原价金额",
      "description": "paid 订单折扣前原价金额合计；单位：分。",
      "type": "simple",
      "type_params": {
        "measure": "m_gross_cents"
      }
    },
    {
      "name": "discount_cents",
      "label": "优惠金额",
      "description": "paid 订单原价减实付的金额合计；退款不冲减原优惠金额；单位：分。",
      "type": "simple",
      "type_params": {
        "measure": "m_discount_cents"
      }
    },
    {
      "name": "buyer_count",
      "label": "购买会员数",
      "description": "统计窗口及筛选条件内有有效订单的不同 CRM 会员账户数，不做跨系统自然人去重。单位：账户。",
      "type": "simple",
      "type_params": {
        "measure": "m_buyer_count_distinct"
      }
    },
    {
      "name": "refund_buyer_count",
      "label": "退款会员数",
      "description": "统计窗口内发生退款的 paid 订单关联的不同 CRM 会员账户数。单位：账户。",
      "type": "simple",
      "type_params": {
        "measure": "m_refund_buyer_count_distinct"
      }
    },
    {
      "name": "selling_store_count",
      "label": "成交门店数",
      "description": "窗口内至少有一笔有效订单的不同订单归属门店数。单位：门店。",
      "type": "simple",
      "type_params": {
        "measure": "m_selling_store_count_distinct"
      }
    },
    {
      "name": "valid_order_items",
      "label": "有效订单商品件数",
      "description": "有效订单中的原始购买件数合计；退款金额不能推算退货件数，此项不是净商品销量。单位：件。",
      "type": "simple",
      "type_params": {
        "measure": "m_valid_order_items"
      }
    },
    {
      "name": "avg_order_value",
      "label": "有效订单均额",
      "description": "净销售额除以有效订单数；分母零时未定义。单位：分／单。",
      "type": "ratio",
      "type_params": {
        "numerator": "net_sales_cents",
        "denominator": "valid_order_count"
      }
    },
    {
      "name": "avg_buyer_value",
      "label": "购买会员人均消费",
      "description": "净销售额除以购买会员数；分母零时未定义。单位：分／账户。",
      "type": "ratio",
      "type_params": {
        "numerator": "net_sales_cents",
        "denominator": "buyer_count"
      }
    },
    {
      "name": "purchase_frequency",
      "label": "购买频次",
      "description": "有效订单数除以购买会员数；分母零时未定义。单位：单／账户。",
      "type": "ratio",
      "type_params": {
        "numerator": "valid_order_count",
        "denominator": "buyer_count"
      }
    },
    {
      "name": "refund_amount_rate",
      "label": "退款金额占比",
      "description": "退款金额除以实付金额；分母零时未定义。单位：比例。",
      "type": "ratio",
      "type_params": {
        "numerator": "refund_cents",
        "denominator": "payment_cents"
      }
    },
    {
      "name": "cancel_rate",
      "label": "取消率",
      "description": "取消订单数除以创建订单数；分母零时未定义。单位：比例。",
      "type": "ratio",
      "type_params": {
        "numerator": "cancelled_order_count",
        "denominator": "order_count"
      }
    },
    {
      "name": "refund_order_rate",
      "label": "退款订单率",
      "description": "退款订单数除以支付订单数；分母零时未定义。单位：比例。",
      "type": "ratio",
      "type_params": {
        "numerator": "refund_order_count",
        "denominator": "paid_order_count"
      }
    },
    {
      "name": "discount_rate",
      "label": "优惠率",
      "description": "优惠金额除以支付订单原价金额；分母零时未定义。单位：比例。",
      "type": "ratio",
      "type_params": {
        "numerator": "discount_cents",
        "denominator": "gross_cents"
      }
    },
    {
      "name": "items_per_order",
      "label": "单均商品件数",
      "description": "有效订单商品件数除以有效订单数；分母零时未定义。单位：件／单。",
      "type": "ratio",
      "type_params": {
        "numerator": "valid_order_items",
        "denominator": "valid_order_count"
      }
    },
    {
      "name": "new_member_count",
      "label": "注册会员数",
      "description": "按注册日期统计新注册 CRM 账户数；可按归属门店和会员等级分组，不等于自然人数。单位：账户。",
      "type": "simple",
      "type_params": {
        "measure": "m_new_member_count_distinct"
      }
    },
    {
      "name": "first_buyer_count",
      "label": "观测期首购会员数",
      "description": "在测试覆盖期内首次有效订单落入查询窗口的不同 CRM 账户数；不代表终身首购。先用全覆盖历史确定首次，再按窗口筛选。单位：账户。",
      "type": "simple",
      "type_params": {
        "measure": "m_first_buyer_count_distinct"
      }
    },
    {
      "name": "first_order_sales_cents",
      "label": "观测期首单净销售额",
      "description": "每个账户在测试覆盖期内第一笔有效订单的净销售额，按该单日期归属；相同日期按订单号排序；单位：分。",
      "type": "simple",
      "type_params": {
        "measure": "m_first_order_sales_cents"
      }
    },
    {
      "name": "first_order_count",
      "label": "观测期首单数",
      "description": "在全测试覆盖期内先为每个账户按日期、订单号排序，其第一笔有效订单落入窗口的单数。单位：单。",
      "type": "simple",
      "type_params": {
        "measure": "m_first_order_count"
      }
    },
    {
      "name": "repeat_order_count",
      "label": "观测期后续购买订单数",
      "description": "账户全测试覆盖期内第二笔及以后的有效订单，按订单日期落入窗口计数；不是月内复购人数。单位：单。",
      "type": "simple",
      "type_params": {
        "measure": "m_repeat_order_count"
      }
    },
    {
      "name": "monthly_buyer_count",
      "label": "月内购买会员数",
      "description": "同一自然月有至少一笔有效订单的账户数，仅整月、全门店口径；允许连续整月按月分别展示，不能跨月直接加总当人数。单位：账户。",
      "type": "simple",
      "type_params": {
        "measure": "m_monthly_buyer_count_distinct"
      }
    },
    {
      "name": "monthly_repeat_buyer_count",
      "label": "月内复购会员数",
      "description": "同一自然月有至少两笔有效订单的账户数，仅整月、全门店口径；不能由全量订单行上的简单条件代替。单位：账户。",
      "type": "simple",
      "type_params": {
        "measure": "m_monthly_repeat_buyer_count_distinct"
      }
    },
    {
      "name": "monthly_repeat_rate",
      "label": "月内复购率",
      "description": "同一自然月的月内复购会员数除以月内购买会员数，仅整月、全门店口径；分母零时未定义；跨多月查询必须按月展示。单位：比例。",
      "type": "ratio",
      "type_params": {
        "numerator": "monthly_repeat_buyer_count",
        "denominator": "monthly_buyer_count"
      }
    },
    {
      "name": "monthly_paid_buyer_count",
      "label": "月末付费会员购买人数",
      "description": "自然月内有至少一笔有效订单、且月末符合总部运营月报付费资格的不同账户数；按P1暂定试算。单位：账户。",
      "type": "simple",
      "type_params": {
        "measure": "m_monthly_paid_buyer_count"
      }
    },
    {
      "name": "monthly_paid_order_count",
      "label": "月末付费会员有效订单数",
      "description": "月末符合付费资格的账户在该自然月的全部有效订单数，按账户资格筛选，不按卡重复；按P1暂定试算。单位：单。",
      "type": "simple",
      "type_params": {
        "measure": "m_monthly_paid_order_count"
      }
    },
    {
      "name": "monthly_paid_sales_cents",
      "label": "月末付费会员净销售额",
      "description": "月末符合付费资格的账户在该自然月的有效订单净销售额合计；按P1暂定试算。单位：分。",
      "type": "simple",
      "type_params": {
        "measure": "m_monthly_paid_sales_cents"
      }
    },
    {
      "name": "monthly_paid_repeat_buyer_count",
